<script>
const webinarTabKey='webinar-tab-{{ $webinar->id }}';const activateWebinarTab=key=>{const tab=document.querySelector(`[data-module-tab="${key}"]`);if(!tab)return;document.querySelectorAll('[data-module-tab]').forEach(item=>item.classList.toggle('active',item===tab));document.querySelectorAll('[data-module-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.modulePanel===key))};document.querySelectorAll('[data-module-tab]').forEach(tab=>tab.addEventListener('click',()=>{activateWebinarTab(tab.dataset.moduleTab);sessionStorage.setItem(webinarTabKey,tab.dataset.moduleTab)}));activateWebinarTab(sessionStorage.getItem(webinarTabKey)||document.querySelector('[data-module-tab].active')?.dataset.moduleTab);if(location.hash)history.replaceState(null,'',location.pathname+location.search);
const showDashboardToast=(message,tone='success')=>{const toast=document.querySelector('#appToast');if(!toast)return;toast.querySelector('.toast-body span').textContent=message;toast.querySelector('.toast-body i').className=`bi bi-${tone==='warning'?'exclamation-circle-fill text-warning':'check-circle-fill text-success'}`;window.bootstrap&&bootstrap.Toast.getOrCreateInstance(toast,{delay:3000}).show()};
document.querySelectorAll('[data-instant-poll] input').forEach(input=>input.addEventListener('change',async()=>{const form=input.form;form.classList.add('poll-submitting');try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error();form.querySelectorAll('input').forEach(option=>option.disabled=true);form.querySelectorAll('.poll-choice').forEach(choice=>choice.classList.add('locked'));input.closest('.poll-choice')?.classList.add('selected');form.previousElementSibling.textContent='Your response is locked for this poll.';showDashboardToast('Your vote was recorded.')}catch{form.classList.remove('poll-submitting');showDashboardToast('Unable to submit your vote.','warning')}}));
const renderAgendaNow=()=>{const now=Date.now();document.querySelectorAll('[data-agenda-start]').forEach(item=>{const start=new Date(item.dataset.agendaStart).getTime(),end=start+(Number(item.dataset.agendaDuration)||30)*60000;item.classList.toggle('is-current',now>=start&&now<end)})};renderAgendaNow();setInterval(renderAgendaNow,30000);
document.addEventListener('DOMContentLoaded',()=>{if(window.Echo){const channel=window.Echo.channel('webinar.{{ $webinar->id }}');channel.listen('.poll.updated',event=>{const form=document.querySelector('[data-instant-poll]');if(!form)return;const total=Math.max(1,event.options.reduce((sum,option)=>sum+Number(option.count),0));event.options.forEach(option=>{const input=form.querySelector(`input[value="${option.id}"]`),choice=input?.closest('.poll-choice');if(!choice)return;const percent=Math.round(Number(option.count)/total*100);choice.querySelector('b').textContent=`${percent}%`;choice.querySelector('.poll-track i').style.width=`${percent}%`})})}});
document.querySelectorAll('[data-comment-form]').forEach(form=>{const input=form.querySelector('textarea'),count=form.querySelector('[data-comment-count]'),button=form.querySelector('button');const update=()=>{count.textContent=input.value.length;button.disabled=input.value.trim().length<2};input.addEventListener('input',update);update()});
document.querySelectorAll('[data-comment-form],[data-feedback-form]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])');const original=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm"></span> Saving...'}try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const payload=await response.json();if(!response.ok)throw new Error(Object.values(payload.errors||{}).flat()[0]||payload.message||'Unable to save.');showDashboardToast(payload.message||'Saved successfully.');if(form.matches('[data-comment-form]')){form.reset();form.querySelector('[data-comment-count]').textContent='0'}}catch(error){showDashboardToast(error.message||'Unable to save.','warning')}finally{if(button){button.disabled=false;button.innerHTML=original}}}));
</script>
@endsection

